selector_to_html = {"a[href=\"#packaging\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Packaging<a class=\"headerlink\" href=\"#packaging\" title=\"Link to this heading\">#</a></h2><p>A Python project <strong>MUST</strong> deliver Python packages with both a source\ndistribution (sdist) and one or more binary distributions (wheels).\nPython packages <strong>MUST</strong> be defined by a <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> file at the\ntop of the project\u2019s source tree; cf. the <a class=\"reference internal\" href=\"toml.html\"><span class=\"doc std std-doc\">TOML Style Guide</span></a>.\nWhile the sections of a <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> file can appear in any order,\nsorting sections alphabetically in decending order is <strong>RECOMMENDED</strong>.</p><p>Standalone modules (unpackaged <code class=\"docutils literal notranslate\"><span class=\"pre\">.py</span></code> files) <strong>MAY</strong> be used as code\nsamples or configuration files.  However, standalone modules <strong>MUST\nNOT</strong> be used as project deliverables since they inherently lack the\nversioning and dependency metadata required to generate a\n<a class=\"reference internal\" href=\"#sbom\"><span class=\"xref myst\">software bill of materials</span></a>.</p>", "a[href=\"toml.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">TOML Style Guide<a class=\"headerlink\" href=\"#toml-style-guide\" title=\"Link to this heading\">#</a></h1><p>Tom\u2019s Obvious Minimal Language (TOML) is a configuration file format\nthat maps to a hash table.  It\u2019s similar to Windows <code class=\"docutils literal notranslate\"><span class=\"pre\">.ini</span></code> files.</p>", "a[href=\"#version-constraints\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Version Constraints<a class=\"headerlink\" href=\"#version-constraints\" title=\"Link to this heading\">#</a></h3><p>To avoid unnecessary developer overhead, a Python project <strong>SHOULD</strong>\nonly set version constraints on dependencies or optional dependencies\nto address capability, compatibility, or security issues.  A Python\nproject <strong>SHOULD NOT</strong> pin specific versions of dependencies or\noptional dependencies.  Any version constraint <strong>MUST</strong> be preceded by\na comment explaining the developer\u2019s rationale for setting the\nconstraint.</p><p>If a Python project depends on an outdated or unreleased version of a\ndependency or an optional dependency, the developer <strong>MUST</strong> log a\nhigh-priority bug report detailing their rationale for setting the\nconstraint.  The reason for setting the constraint <strong>MUST</strong> be\naddressed, and the constraint <strong>MUST</strong> be removed, before the next\nmajor release.</p>", "a[href=\"#build-system\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Build System<a class=\"headerlink\" href=\"#build-system\" title=\"Link to this heading\">#</a></h3><p>A Python project <strong>MUST</strong> use\n<a class=\"reference external\" href=\"https://pypi.org/project/setuptools/\">setuptools</a> version 61 or newer\nas the build system.  Project setup scripts and configuration files\nsuch as <code class=\"docutils literal notranslate\"><span class=\"pre\">setup.py</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">setup.cfg</span></code> <strong>SHOULD NOT</strong> be used.</p>", "a[href=\"#python-style-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python Style Guide<a class=\"headerlink\" href=\"#python-style-guide\" title=\"Link to this heading\">#</a></h1><p>This extends <a class=\"reference external\" href=\"https://peps.python.org/pep-0008/\">PEP 8</a>, the Python\ncommunity\u2019s style guide, and the\n<a class=\"reference external\" href=\"https://packaging.python.org/\"><em>Python Packaging User Guide</em></a>.</p>", "a[href=\"#project-settings\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Project Settings<a class=\"headerlink\" href=\"#project-settings\" title=\"Link to this heading\">#</a></h3><p>The following project settings are <strong>REQUIRED</strong>:</p>", "a[href=\"#project-summary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Project Summary<a class=\"headerlink\" href=\"#project-summary\" title=\"Link to this heading\">#</a></h3><p>A Python project <strong>MUST</strong> include the project summary document,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">README.md</span></code>, with a content type of <code class=\"docutils literal notranslate\"><span class=\"pre\">text/markdown</span></code>.</p>", "a[href=\"#distribution-layout\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Distribution Layout<a class=\"headerlink\" href=\"#distribution-layout\" title=\"Link to this heading\">#</a></h3><p>To prevent accidental usage of in-development code, all Python\nprojects <strong>MUST</strong> follow\n<a class=\"reference external\" href=\"https://packaging.python.org/en/latest/discussions/src-layout-vs-flat-layout/\">the \u201csrc\u201d distribution layout</a>.</p>", "a[href=\"#optional-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Optional Dependencies<a class=\"headerlink\" href=\"#optional-dependencies\" title=\"Link to this heading\">#</a></h3><p>A Python project <strong>MUST</strong> define the following optional dependency\nlists:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
